package local.tvmorph.tv;
import android.app.Activity;import android.content.*;import android.net.Uri;import android.os.*;import android.webkit.*;import org.json.*;
/** Same Cleaner presentation on Android TV, Fire TV and phone, with Android's folder permission UI. */
public final class CleanerActivity extends Activity {
 private WebView web;private CleanerFiles files;private Uri tree;private volatile boolean picking,destroyed;private String requestedScope="files";
 private final java.util.concurrent.ExecutorService worker=java.util.concurrent.Executors.newSingleThreadExecutor();
 public void onCreate(Bundle saved){super.onCreate(saved);files=new CleanerFiles(this);String value=getPreferences(0).getString("folder","");if(!value.isEmpty())tree=Uri.parse(value);web=new WebView(this);web.setBackgroundColor(0xff0b1a2c);setContentView(web);web.getSettings().setJavaScriptEnabled(true);web.getSettings().setUseWideViewPort(true);web.getSettings().setLoadWithOverviewMode(true);web.getSettings().setSupportZoom(false);web.getSettings().setAllowFileAccess(false);web.getSettings().setAllowContentAccess(false);web.addJavascriptInterface(new Backend(),"CleanerNative");web.setWebViewClient(new WebViewClient(){public boolean shouldOverrideUrlLoading(WebView v,String url){return true;}});web.loadUrl("file:///android_asset/cleaner/cleaner-native.html");}
 private Intent folderPicker(){Intent intent=new Intent("android.intent.action.OPEN_DOCUMENT_TREE").addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION);java.util.List<android.content.pm.ResolveInfo> handlers=getPackageManager().queryIntentActivities(intent,android.content.pm.PackageManager.MATCH_DEFAULT_ONLY);for(android.content.pm.ResolveInfo handler:handlers){android.content.pm.ActivityInfo info=handler.activityInfo;if(info!=null&&info.enabled&&info.exported&&!"android".equals(info.packageName))return intent.setComponent(new ComponentName(info.packageName,info.name));}return null;}
 private final class Backend {
  @JavascriptInterface public boolean isTelevision(){return (getResources().getConfiguration().uiMode&android.content.res.Configuration.UI_MODE_TYPE_MASK)==android.content.res.Configuration.UI_MODE_TYPE_TELEVISION;}
  @JavascriptInterface public boolean canChooseFolder(){return folderPicker()!=null;}
  @JavascriptInterface public String storageJson(){try{StatFs disk=new StatFs(getFilesDir().getAbsolutePath());return new JSONObject().put("total",disk.getTotalBytes()).put("free",disk.getAvailableBytes()).toString();}catch(Exception e){return "{}";}}
  @JavascriptInterface public void storageSettings(){runOnUiThread(new Runnable(){public void run(){try{startActivity(new Intent(android.provider.Settings.ACTION_INTERNAL_STORAGE_SETTINGS));}catch(Exception ignored){}}});}
  @JavascriptInterface public String themeJson(){try{String raw=getIntent().getStringExtra("cleanerTheme");if(raw!=null&&raw.length()<=6000){JSONObject input=new JSONObject(raw),tokens=input.optJSONObject("tokens"),safe=new JSONObject();if(tokens!=null){java.util.Iterator<String> keys=tokens.keys();while(keys.hasNext()){String key=keys.next(),value=tokens.optString(key);if(key.matches("--ui-[a-z-]+")&&value.length()<200&&!value.toLowerCase(java.util.Locale.US).contains("url("))safe.put(key,value);}}String background=input.optString("background","");if(background.length()>200||!background.matches("(?:assets|reference-assets)/[A-Za-z0-9_./-]+")||background.contains(".."))background="";return new JSONObject().put("language",input.optString("language","en")).put("tokens",safe).put("background",background).toString();}android.content.SharedPreferences p=getSharedPreferences("tvmorph-ui",0);JSONObject tokens=new JSONObject();String[][] mapping={{"uiBg","--ui-bg"},{"uiSurface","--ui-bg-raised"},{"uiAccent","--ui-accent"},{"uiText","--ui-text"}};for(String[] pair:mapping){String value=p.getString(pair[0],"");if(value.matches("#[0-9a-fA-F]{6}"))tokens.put(pair[1],value);}return new JSONObject().put("language",p.getString("language","en")).put("tokens",tokens).toString();}catch(Exception ignored){return "{}";}}
  @JavascriptInterface public String scan(String scope){try{if("folder".equals(scope)){final Intent picker=folderPicker();if(picker==null)return "{\"error\":\"Folder selection is unavailable on this TV. Use the direct installation-file or cache scan.\"}";if(!picking){requestedScope="files";picking=true;runOnUiThread(new Runnable(){public void run(){try{startActivityForResult(picker,19);}catch(Exception e){picking=false;folderNotice("Folder selection unavailable. Use the direct scan. / استخدم الفحص المباشر؛ اختيار المجلد غير متاح.");}}});}return "{\"pendingFolder\":true,\"files\":[],\"bytes\":0}";}return files.scan(scope,tree).toString();}catch(Exception e){return failure(e);}}
  @JavascriptInterface public void exit(){runOnUiThread(new Runnable(){public void run(){finish();}});}
  @JavascriptInterface public void request(final String id,final String action,final String payload){
   if(id==null||!id.matches("cleaner-[0-9]{1,9}")||payload==null||payload.length()>1000000||!("scan".equals(action)||"remove".equals(action))||destroyed)return;
   worker.execute(new Runnable(){public void run(){if(destroyed)return;final String result="scan".equals(action)?scan(payload):remove(payload);runOnUiThread(new Runnable(){public void run(){if(!destroyed&&web!=null)web.evaluateJavascript("window.cleanerResult&&window.cleanerResult("+JSONObject.quote(id)+","+JSONObject.quote(result)+")",null);}});}});
  }
  @JavascriptInterface public String remove(String selected){try{return files.remove(selected).toString();}catch(Exception e){return failure(e);}}
 }
 private String failure(Exception e){return "{\"files\":[],\"ids\":[],\"bytes\":0,\"errors\":["+JSONObject.quote(String.valueOf(e.getMessage()))+"]}";}
 private void folderNotice(final String message){if(web!=null)web.postDelayed(new Runnable(){public void run(){if(web!=null)web.evaluateJavascript("if(window.MorphCleaner)MorphCleaner.folderResult("+JSONObject.quote(message)+")",null);}},100);}
 protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request!=19)return;picking=false;if(result==RESULT_OK&&data!=null&&data.getData()!=null){tree=data.getData();try{getContentResolver().takePersistableUriPermission(tree,data.getFlags()&(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION));getPreferences(0).edit().putString("folder",tree.toString()).apply();}catch(Exception ignored){}web.evaluateJavascript("if(MorphCleaner.isOpen())MorphCleaner.scan("+JSONObject.quote(requestedScope)+")",null);}else folderNotice("");}
 public void onBackPressed(){finish();}protected void onDestroy(){destroyed=true;worker.shutdownNow();if(web!=null){web.removeJavascriptInterface("CleanerNative");web.destroy();web=null;}super.onDestroy();}
}
